#include <stdlib.h>
#include <string.h>

#define MAX 100005

int main() {
    int t;
    scanf("%d", &t);
    getchar();

    while (t--) {
        char line[1000000];
        fgets(line, sizeof(line), stdin);

        int arr[MAX];
        int n = 0;

        char *token = strtok(line, " \n");

        while (token != NULL) {
            arr[n++] = atoi(token);
            token = strtok(NULL, " \n");
        }

        int ans = arraySum(arr, n);

        printf("%d\n", ans);
        printf("~\n");
    }

    return 0;
}

